const TEXT_TAB_TIP: &str = " Use <TAB> to rearrange tables.";

impl HelpText {
    pub fn render(&self, frame: &mut Frame, rect: Rect) {
        let pause_content = if self.paused {
            TEXT_WHEN_PAUSED
